-- Default LSP settings.
--
-- Do not edit this file to change them. Either pass the same shape to setup():
--
--		require('genja').setup({ lsp = { enabled = { php = true } } })
--
-- or, for one machine only, put a lua/genja/lsp/local.lua in your Neovim
-- config directory. It has the same shape, is merged over everything else,
-- and is meant to stay out of git. Example:
--
--		return { enabled = { php = true, python = false } }
--		return { enabled = { php = true, powershell = false } }

---@class genja.lsp.Opts
---@field enabled? table<string, boolean>
---@field mason? table
---@field diagnostics? vim.diagnostic.Opts|false
---@field phpactor_wsl? { distro?: string, install?: boolean }

---@type genja.lsp.Opts
return {
	-- Keys are file names in lua/genja/lang/ sans «.lua»
	-- false or absent: the language is skipped and nothing is installed for it.
	-- i.e you need to add a lang-key here after installing a new language
	enabled = {
		-- shells
		powershell = false,
		bash = true,
		lua = true,
		vim = true,

		-- langs
		typescript = false,
		c_cpp = false,
		go = false,

		-- scrapt itropretor langs
		python = false,
		php = false,
	},

	-- Windows: phpactor runs inside WSL (lua/genja/lang/php.lua, doc/phpactor-wsl.md).
	phpactor_wsl = {
		distro = nil, -- wsl.exe -d <distro>; nil: the default distro (`wsl -l -v`)
		install = true, -- install PHP and phpactor in the distro when missing
	},

	-- Passed to require('mason').setup().
	mason = {
		ui = { border = 'double' },
	},

	-- Passed to vim.diagnostic.config(). false: leave diagnostics alone.
	-- Neovim 0.11 turned inline virtual text off by default.
	-- Quieter alternatives are in the README.
	diagnostics = {
		virtual_text = true,
		severity_sort = true,
	},
}
